using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Windows.Automation;
using static TeronWoWLauncher.Models.PatchStep;

namespace TeronWoWLauncher.Models;

/// <summary>Which stage of the fixed patch order a patch belongs to. Lower value = applied first.</summary>
public enum PatchCategory
{
    /// <summary>Applied first: disables the client's file-integrity/signature checks.</summary>
    SignatureRemoval = 0,

    /// <summary>Applied second: the quality-of-life executable tweaks.</summary>
    VanillaTweak = 1,

    QuestLogTweak = 2,
}

/// <summary>
/// A single byte-level edit. Two shapes are supported:
///
///   * <b>Offset edit</b> (<see cref="Offset"/> &gt;= 0): write <see cref="Write"/> at that fixed
///     file offset. Reliable because we always patch the known pristine client. When
///     <see cref="AcceptBefore"/> is set, the current bytes must match one of those sequences (a
///     build-safety fingerprint) unless they already equal <see cref="Write"/>.
///
///   * <b>Pattern edit</b> (<see cref="Offset"/> &lt; 0): locate <see cref="Find"/> in the image and
///     overwrite it with <see cref="Write"/> (same length). <see cref="Find"/> also acts as the
///     pristine "before" state for detection.
/// </summary>
public sealed class PatchStep(long offset, byte[] write, byte[]? find = null, byte[][]? acceptBefore = null, byte[]? writeOff = null)
{
    public long Offset { get; init; } = offset;

    public byte[]? Find { get; init; } = find;

    public byte[]? Write { get; init; } = write;

    /// <summary>Offset mode only: acceptable pre-patch byte sequences at the offset. Null = no check.</summary>
    public byte[][]? AcceptBefore { get; init; } = acceptBefore;

    /// <summary>
    /// Offset mode only: the bytes to write back when the owning patch is disabled during a rebuild.
    /// Null means "leave whatever the pristine backup already has" - correct for a genuinely pristine
    /// backup, where disabled and the backup's own value already coincide. Non-null is for patches
    /// whose backup can legitimately already contain the "on" bytes (e.g. a community client that
    /// ships a tweak baked in) - disabling then means actively reverting to this value rather than
    /// merely skipping, since skipping would silently leave the baked-in value in place.
    /// </summary>
    public byte[]? WriteOff { get; init; } = writeOff;

    public sealed class QuestLogPatchStruct(int offset, int length, int rva, int imageSize, IReadOnlyList<QuestLogPatcher.QuestRangeStruct> questRanges)
    {
        private readonly string SectionHeaderBase64 = "Lm9jdG9xbAAAUAAAAGCSAABQAAAA4EoAAAAAAAAAAAAAAAAAYAAA4A==";
        private readonly string SectionPayloadBase64 = "";
        public int Offset { get; init; } = offset;
        public int Length { get; init; } = length;
        public int RVA { get; init; } = rva;
        public int ImageSize { get; init; } = imageSize;
        public IReadOnlyList<QuestLogPatcher.QuestRangeStruct> QuestRanges { get; init; } = questRanges;
        internal byte[] SectionHeaderBytes => Convert.FromBase64String(SectionHeaderBase64);
        internal byte[] SectionPayloadBytes => Convert.FromBase64String(SectionPayloadBase64);
    }
}

/// <summary>Optional numeric knob for a patch (e.g. render distance, nameplate range).</summary>
public sealed class PatchParameter
{
    public double Min { get; init; }
    public double Max { get; init; }
    public double Default { get; init; }

    /// <summary>True when the value is shown/edited as a whole number (every current tweak).</summary>
    public bool IsInteger { get; init; }

    /// <summary>Optional unit shown in the UI, e.g. "yds" or "rad".</summary>
    public string? Unit { get; init; }

    // Optional QuestPatch parameters
    public bool IsQuestPatch { get; init; } = false;
    //default quest log array can contain 20 quest entries (Vanilla and Turtle WoW clients)
}

/// <summary>
/// One user-selectable patch. Its concrete byte edits are produced by <see cref="BuildSteps"/>,
/// which receives the chosen parameter value (null for simple on/off patches). Keeping the edits
/// behind a factory lets a parameterized patch encode the user's value into the replacement bytes.
/// </summary>
public sealed class PatchDefinition
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public required string Description { get; init; }
    public required PatchCategory Category { get; init; }

    /// <summary>
    /// True for the small set of tweaks that should be grouped and labeled as required reading before
    /// using custom MPQ patches (Signature Removal, Large Address Aware) - orthogonal to
    /// <see cref="Category"/>, which only controls WoW.exe rebuild order. Purely a UI grouping/labeling
    /// concern; it has no effect on patching behavior itself.
    /// </summary>
    public bool MandatoryForMpq { get; init; }

    /// <summary>
    /// True for a patch whose pristine backup can legitimately already contain its "on" bytes (a
    /// community client tweak baked in at the factory) - a fresh directory pre-checks this patch's
    /// checkbox instead of leaving it unchecked like everything else, so the first sync is a no-op
    /// against what the client already ships rather than an unrequested revert. See
    /// <see cref="DirectorySettings.PatchDefaultsSeeded"/> for how this is applied only once.
    /// </summary>
    public bool DefaultEnabled { get; init; }

    /// <summary>Non-null when the patch exposes a numeric value to the user.</summary>
    public PatchParameter? Parameter { get; init; }

    /// <summary>Build the concrete edits for this patch given the chosen parameter value (if any). The property is marked as nullable as is nulled by default, if needed, build steps can be introduced.</summary>
    public required Func<double?, IReadOnlyList<PatchStep>>? BuildSteps { get; init; } = null;
    // optional QuestLog patch steps builder for QuestLogTweak category
    public required Func<int?, IReadOnlyList<QuestLogPatchStruct>>? BuildQuestLogSteps { get; init; } = null;
}

public sealed class QuestLogPatcher
{
    public class QuestRangeStruct(int rangeStart, int rangeEnd, string rangeContent)
    {
        public int GetRangeLength() => RangeEnd - RangeStart;
        public (int Start, byte[] Content, int End) ReturnValues() => (RangeStart, RangeContent, RangeEnd);

        internal int RangeStart { get; init; } = rangeStart;
        internal int RangeEnd { get; init; } = rangeEnd;
        internal byte[] RangeContent { get; init; } = Convert.FromBase64String(rangeContent);
    }

    public sealed class ByteHelpers
    {
        internal static ushort ReadUInt16(byte[] b, int o) => BitConverter.ToUInt16(b, o);
        internal static uint ReadUInt32(byte[] b, int o) => BitConverter.ToUInt32(b, o);
        internal static int ReadInt32(byte[] b, int o) => BitConverter.ToInt32(b, o);
        internal static void WriteUInt16(byte[] b, int o, ushort value) => BitConverter.GetBytes(value).CopyTo(b, o);
        internal static void WriteUInt32(byte[] b, int o, uint value) => BitConverter.GetBytes(value).CopyTo(b, o);
        internal static string Sha256(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
        internal static ushort GetNumberOfSections(byte[] image)
        {
            int peOffset = ReadInt32(image, 0x3C);
            return ReadUInt16(image, peOffset + 6);
        }
        internal static int GetSectionTableOffset(byte[] image)
        {
            int peOffset = ReadInt32(image, 0x3C);
            ushort optionalHeaderSize = ReadUInt16(image, peOffset + 20);
            return peOffset + 24 + optionalHeaderSize;
        }
    }

    private static void ReadSectionHeader(byte[] image, int index, out string name, out uint virtualSize, out uint virtualAddress, out uint rawSize, out uint rawPointer, out uint characteristics)
    {
        int tableOffset = ByteHelpers.GetSectionTableOffset(image);
        int o = tableOffset + index * 40;

        if (o < 0 || o + 40 > image.Length)
        {
            throw new InvalidDataException("Section header is outside the file.");
        }

        int zero = Array.IndexOf(image, (byte)0, o, 8);
        int nameLength = zero >= 0 ? zero - o : 8;

        name = Encoding.ASCII.GetString(image, o, nameLength);
        virtualSize = ByteHelpers.ReadUInt32(image, o + 8);
        virtualAddress = ByteHelpers.ReadUInt32(image, o + 12);
        rawSize = ByteHelpers.ReadUInt32(image, o + 16);
        rawPointer = ByteHelpers.ReadUInt32(image, o + 20);
        characteristics = ByteHelpers.ReadUInt32(image, o + 36);
    }

    internal static bool VerifyPatchedQuestBytes(byte[] patched, byte[][] expected, IReadOnlyList<QuestRangeStruct> questRanges)
    {
        for (int r = 0; r < questRanges.Count; r++)
        {
            var range = questRanges[r];
            byte[] data = expected[r];

            for (int i = 0; i < data.Length; i++)
            {
                if (patched[range.RangeStart + i] != data[i])
                {
                    throw new InvalidDataException($"Quest patch verification failed at file offset 0x{range.RangeStart + i:X}.");
                }
            }
        }

        // If all quest ranges match the expected bytes, the verification is successful
        return true;
    }

    internal static bool VerifySection(byte[] image, QuestLogPatchStruct patch)
    {
        ReadSectionHeader(image, 6, out string name, out uint virtualSize, out uint virtualAddress, out uint rawSize, out uint rawPointer, out uint characteristics);

        // rawSize = SizeOfRawData (section header field) = the on-disk payload size = patch.Length.
        // patch.ImageSize is SizeOfImage (page-aligned virtual total), which lives in the Optional Header — not here.
        if (name != ".octoql" || virtualSize != patch.Length || virtualAddress != patch.RVA || rawSize != patch.Length || rawPointer != patch.Offset || characteristics != 0xE0000060)
        {
            throw new InvalidDataException("Patched .octoql section verification failed.");
        }

        if (ByteHelpers.GetNumberOfSections(image) != 7)
        {

            throw new InvalidDataException("Patched section count is not 7.");
        }

        int peOffset = ByteHelpers.ReadInt32(image, 0x3C);
        if (ByteHelpers.ReadUInt32(image, peOffset + 24 + 56) != patch.ImageSize)
        {
            throw new InvalidDataException("Patched SizeOfImage is incorrect.");
        }

        // File size = original file size (patch.Offset = PointerToRawData = append point) + raw payload (patch.Length).
        // Do NOT use patch.ImageSize here — that is SizeOfImage (virtual/page-aligned), not the on-disk byte count.
        if (image.Length != patch.Offset + patch.Length)
        {
            throw new InvalidDataException("Patched file size is incorrect.");
        }

        //if the patched .octoql section and SizeOfImage are correct, then the quest log patch is verified successfully
        return true;
    }

    internal static bool ValidatePeLayout(byte[] image, string name)
    {
        if (image.Length < 0x1000)
        {
            throw new InvalidDataException($".octoql: file is too small.");
        }

        ArgumentNullException.ThrowIfNull(name);

        if (ByteHelpers.ReadUInt16(image, 0) != 0x5A4D)
        {
            throw new InvalidDataException($".octoql: missing MZ header.");
        }

        int peOffset = ByteHelpers.ReadInt32(image, 0x3C);
        if (peOffset < 0 || peOffset + 24 > image.Length || ByteHelpers.ReadUInt32(image, peOffset) != 0x00004550)
        {
            throw new InvalidDataException($".octoql: invalid PE header.");
        }

        ushort machine = ByteHelpers.ReadUInt16(image, peOffset + 4);
        if (machine != 0x14C)
        {
            throw new InvalidDataException($".octoql: expected 32-bit x86 PE.");
        }

        // validate the final patched layout of the PE file, including the .octoql section and SizeOfImage
        return true;
    }
}
